#include <iostream>
#include <vector>
using namespace std;

vector<int> read_input_line() {
    vector<int> result;
    int temp;
    while (cin >> temp) {
        result.push_back(temp);
        if (cin.peek() == '\n' || cin.eof()) break;
    }
    return result;
}

long long compute_power(long long base, long long exp, long long mod) {
    long long result = 1;
    while (exp > 0) {
        if (exp % 2 == 1) {
            result = (result * base) % mod;
        }
        base = (base * base) % mod;
        exp /= 2;
    }
    return result;
}

int main() {
    vector<int> input_vals = read_input_line();
    int p = input_vals[0];
    int k = input_vals[1];
    const long long MOD = 1000000007;
    long long answer_value = 0;

    if (k == 0) {
        answer_value = compute_power(p, p - 1, MOD);
    } else {
        for (int i = 1; i < p; ++i) {
            if ((p - 1) % i == 0 && compute_power(k, i, p) == 1) {
                answer_value = compute_power(p, (p - 1) / i, MOD);
                if (k == 1) {
                    answer_value = (answer_value * p) % MOD;
                }
                break;
            }
        }
    }
    cout << answer_value << endl;
    return 0;
}
